def topic_matches(pattern: str, topic: str) -> bool:
    p = pattern.split('.')
    t = topic.split('.')
    return _match(p, t)

def _match(p, t):
    if not p:
        return not t
    if p[0] == '**':
        # '**' matches zero or more whole segments
        return _match(p[1:], t) or (bool(t) and _match(p, t[1:]))
    if not t:
        return False
    if p[0] == '*':
        # '*' matches exactly one segment
        return _match(p[1:], t[1:])
    return p[0] == t[0] and _match(p[1:], t[1:])

